#define REG(base, off) (*(volatile uint32_t *)(uintptr_t)((base) + (off)))
#define BIT(n)         (1u << (n))

enum { GPIO_MODE_INPUT = 0u, GPIO_MODE_OUTPUT = 1u, GPIO_MODE_AF = 2u };

static void delay(volatile uint32_t count)
{
    while (count--) { }
}

/* ---------------------------------------------------------------- GPIO --- */

static void gpio_set_mode(uint32_t port, uint32_t pin, uint32_t mode)
{
    uint32_t v = REG(port, GPIO_MODER);
    v &= ~(3u << (pin * 2u));
    v |= (mode << (pin * 2u));
    REG(port, GPIO_MODER) = v;
}

static void gpio_set_push_pull_fast(uint32_t port, uint32_t pin)
{
    REG(port, GPIO_OTYPER) &= ~BIT(pin);
    REG(port, GPIO_OSPEEDR) |= (3u << (pin * 2u));
    REG(port, GPIO_PUPDR) &= ~(3u << (pin * 2u));
}

static void gpio_set_af(uint32_t port, uint32_t pin, uint32_t af)
{
    uint32_t off   = (pin < 8u) ? GPIO_AFRL : GPIO_AFRH;
    uint32_t shift = (pin % 8u) * 4u;
    uint32_t v = REG(port, off);
    v &= ~(0xFu << shift);
    v |= (af << shift);
    REG(port, off) = v;
}

static void gpio_write(uint32_t port, uint32_t pin, int high)
{
    REG(port, GPIO_BSRR) = high ? BIT(pin) : BIT(pin + 16u);
}

static int gpio_read(uint32_t port, uint32_t pin)
{
    return (REG(port, GPIO_IDR) & BIT(pin)) != 0u;
}

static void gpio_init(void)
{
    REG(RCC_BASE, RCC_AHB2ENR) |= BIT(SCK_PORT_EN_BIT) | BIT(MOSI_PORT_EN_BIT)
                                | BIT(LE_PORT_EN_BIT)  | BIT(CE_PORT_EN_BIT)
                                | BIT(LD_PORT_EN_BIT);
    (void)REG(RCC_BASE, RCC_AHB2ENR);

    gpio_set_af(SCK_PORT_BASE, SCK_PIN, SPI1_AF);
    gpio_set_push_pull_fast(SCK_PORT_BASE, SCK_PIN);
    gpio_set_mode(SCK_PORT_BASE, SCK_PIN, GPIO_MODE_AF);

    gpio_set_af(MOSI_PORT_BASE, MOSI_PIN, SPI1_AF);
    gpio_set_push_pull_fast(MOSI_PORT_BASE, MOSI_PIN);
    gpio_set_mode(MOSI_PORT_BASE, MOSI_PIN, GPIO_MODE_AF);

    gpio_write(LE_PORT_BASE, LE_PIN, 0);
    gpio_set_push_pull_fast(LE_PORT_BASE, LE_PIN);
    gpio_set_mode(LE_PORT_BASE, LE_PIN, GPIO_MODE_OUTPUT);

    gpio_write(CE_PORT_BASE, CE_PIN, 0);
    gpio_set_push_pull_fast(CE_PORT_BASE, CE_PIN);
    gpio_set_mode(CE_PORT_BASE, CE_PIN, GPIO_MODE_OUTPUT);

    REG(LD_PORT_BASE, GPIO_PUPDR) &= ~(3u << (LD_PIN * 2u));
    gpio_set_mode(LD_PORT_BASE, LD_PIN, GPIO_MODE_INPUT);
}

/* ----------------------------------------------------------------- SPI --- */

static void spi1_init(void)
{
    REG(RCC_BASE, RCC_APB2ENR) |= BIT(SPI1_EN_BIT);
    (void)REG(RCC_BASE, RCC_APB2ENR);

    REG(SPI1_BASE, SPI_CR1) &= ~BIT(SPI_CR1_SPE_BIT);

    REG(SPI1_BASE, SPI_CFG1) = (SPI_CFG1_DSIZE_VAL << SPI_CFG1_DSIZE_POS)
                             | (SPI_CFG1_MBR_VAL   << SPI_CFG1_MBR_POS);

    /* CPOL, CPHA and LSBFRST are left 0: SPI mode 0, MSB first. */
    REG(SPI1_BASE, SPI_CFG2) = BIT(SPI_CFG2_MASTER_BIT) | BIT(SPI_CFG2_SSM_BIT);

    REG(SPI1_BASE, SPI_CR1) = BIT(SPI_CR1_SSI_BIT);
}

/* Sends one 32-bit frame. TSIZE can only be written while SPE=0, and the
 * SPI must be disabled after EOT before the next transaction. */
static void spi1_send32(uint32_t word)
{
    REG(SPI1_BASE, SPI_CR2) = 1u;
    REG(SPI1_BASE, SPI_CR1) |= BIT(SPI_CR1_SPE_BIT);
    REG(SPI1_BASE, SPI_CR1) |= BIT(SPI_CR1_CSTART_BIT);

    while ((REG(SPI1_BASE, SPI_SR) & BIT(SPI_SR_TXP_BIT)) == 0u) { }
    REG(SPI1_BASE, SPI_TXDR) = word;

    while ((REG(SPI1_BASE, SPI_SR) & BIT(SPI_SR_EOT_BIT)) == 0u) { }
    REG(SPI1_BASE, SPI_IFCR) = BIT(SPI_IFCR_EOTC_BIT) | BIT(SPI_IFCR_TXTFC_BIT);

    REG(SPI1_BASE, SPI_CR1) &= ~BIT(SPI_CR1_SPE_BIT);
}

/* ------------------------------------------------------------- ADF4351 --- */

static void adf4351_write(uint32_t word)
{
    spi1_send32(word);
    gpio_write(LE_PORT_BASE, LE_PIN, 1);
    delay(10);
    gpio_write(LE_PORT_BASE, LE_PIN, 0);
}

static void adf4351_init(void)
{
    gpio_write(CE_PORT_BASE, CE_PIN, 1);
    delay(100000);

    /* R0 must be written last: it triggers the VCO band select / lock. */
    adf4351_write(ADF_R5);
    adf4351_write(ADF_R4);
    adf4351_write(ADF_R3);
    adf4351_write(ADF_R2);
    adf4351_write(ADF_R1);
    adf4351_write(ADF_R0);
}

static int adf4351_locked(void)
{
    return gpio_read(LD_PORT_BASE, LD_PIN);
}

/* ---------------------------------------------------------------- main --- */

int main(void)
{
    gpio_init();
    spi1_init();
    adf4351_init();

    for (;;)
    {
        volatile int locked = adf4351_locked();
        (void)locked;
    }
}
